import sys

def resulting_frequency(changes):
    freq = 0
    for x in changes:
        freq += x
    return freq

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    parts = [p.strip() for p in data.split(',')]
    changes = [int(p) for p in parts if p]
    print(resulting_frequency(changes))

if __name__ == "__main__":
    main()

import sys
from collections import Counter

def checksum_box_ids(ids):
    twos = 0
    threes = 0

    for s in ids:
        counts = Counter(s).values()
        if 2 in counts:
            twos += 1
        if 3 in counts:
            threes += 1

    return twos * threes

def main():
    ids = [line.strip() for line in sys.stdin if line.strip()]
    print(checksum_box_ids(ids))

if __name__ == "__main__":
    main()

