from collections import Counter

def solve():
    ids = [line.strip() for line in sys.stdin if line.strip()]

    # Part 1: checksum
    twos = 0
    threes = 0
    for s in ids:
        counts = Counter(s).values()
        if 2 in counts:
            twos += 1
        if 3 in counts:
            threes += 1
    checksum = twos * threes

    # Part 2: find two IDs differing by exactly one character
    # Efficient approach: for each position, remove that char and look for duplicates.
    seen = {}
    common = None
    for s in ids:
        for i in range(len(s)):
            key = s[:i] + s[i+1:]
            if key in seen:
                common = key
                break
            seen[key] = s
        if common is not None:
            break

    # Output format: problem statement expects the common letters for Part Two.
    # (If you want both parts, print checksum first on its own line.)
    if common is None:
        common = ""
    sys.stdout.write(common)

if __name__ == "__main__":
    solve()

