import sys
import re

def solve(data: str) -> int:
    claims = []
    pat = re.compile(r'#(\d+)\s*@\s*(\d+),(\d+):\s*(\d+)x(\d+)')

    for line in data.strip().splitlines():
        line = line.strip()
        if not line:
            continue
        m = pat.match(line)
        if not m:
            continue
        _, x, y, w, h = m.groups()
        x, y, w, h = map(int, (x, y, w, h))
        claims.append((x, y, w, h))

    # Count how many claims cover each unit square
    grid = {}
    for x, y, w, h in claims:
        for i in range(x, x + w):
            for j in range(y, y + h):
                grid[(i, j)] = grid.get((i, j), 0) + 1

    # Sum squares covered by 2 or more claims
    return sum(1 for v in grid.values() if v >= 2)

if __name__ == "__main__":
    data = sys.stdin.read()
    print(solve(data))

