def solve(data: str):
    claims = []
    pattern = re.compile(r'#(\d+)\s*@\s*(\d+),(\d+):\s*(\d+)x(\d+)')

    for line in data.strip().splitlines():
        line = line.strip()
        if not line:
            continue
        m = pattern.match(line)
        if not m:
            continue
        cid, x, y, w, h = map(int, m.groups())
        claims.append((cid, x, y, w, h))

    # Part 1: count overlaps (not required for part 2 output, but we compute anyway)
    fabric = {}  # (x,y) -> count
    for _, x, y, w, h in claims:
        for i in range(x, x + w):
            for j in range(y, y + h):
                fabric[(i, j)] = fabric.get((i, j), 0) + 1

    # Part 2: find the only claim that doesn't overlap any square
    for cid, x, y, w, h in claims:
        intact = True
        for i in range(x, x + w):
            for j in range(y, y + h):
                if fabric.get((i, j), 0) != 1:
                    intact = False
                    break
            if not intact:
                break
        if intact:
            return str(cid)

    return ""  # should not happen with valid input

