import sys
import re
from collections import defaultdict

def solve(lines):
    logs = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        # Extract timestamp and message
        m = re.match(r"\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2})\] (.*)", line)
        if not m:
            continue
        ts, msg = m.group(1), m.group(2)
        logs.append((ts, msg))

    # Sort chronologically
    logs.sort(key=lambda x: x[0])

    # sleep_count[guard][minute] = number of times asleep at that minute
    sleep_count = defaultdict(lambda: [0] * 60)
    total_sleep = defaultdict(int)

    current_guard = None
    asleep_minute = None

    for ts, msg in logs:
        if "Guard #" in msg and "begins shift" in msg:
            current_guard = int(re.search(r"Guard #(\d+)", msg).group(1))
        elif msg == "falls asleep":
            asleep_minute = int(ts[-2:])  # minute part
        elif msg == "wakes up":
            wake_minute = int(ts[-2:])
            # asleep includes minute asleep_minute, excludes wake_minute
            for m in range(asleep_minute, wake_minute):
                sleep_count[current_guard][m] += 1
                total_sleep[current_guard] += 1

    # Strategy 2: guard most frequently asleep on the same minute
    best_guard = None
    best_minute = None
    best_times = -1

    for guard, minutes in sleep_count.items():
        for minute, times in enumerate(minutes):
            if times > best_times:
                best_times = times
                best_guard = guard
                best_minute = minute

    return str(best_guard * best_minute)

def main():
    lines = sys.stdin.read().splitlines()
    print(solve(lines))

if __name__ == "__main__":
    main()

