import sys

def reacts(a, b):
    # Same letter, opposite polarity
    return a != b and a.lower() == b.lower()

def fully_react(poly: str) -> str:
    stack = []
    for ch in poly.strip():
        if stack and reacts(stack[-1], ch):
            stack.pop()
        else:
            stack.append(ch)
    return ''.join(stack)

def solve():
    polymer = sys.stdin.read().strip()
    if not polymer:
        return

    # All unit types (letters) present
    types = set(ch.lower() for ch in polymer)

    best = None
    for t in types:
        filtered = [ch for ch in polymer if ch.lower() != t]
        reacted = fully_react(''.join(filtered))
        length = len(reacted)
        if best is None or length < best:
            best = length

    print(best)

if __name__ == "__main__":
    solve()

