import sys
from collections import defaultdict

def solve(data: str) -> str:
    prereq = defaultdict(set)   # step -> set of prerequisites
    steps = set()

    for line in data.strip().splitlines():
        if not line.strip():
            continue
        parts = line.split()
        a = parts[1]  # prerequisite step letter
        b = parts[7]  # dependent step letter
        steps.add(a)
        steps.add(b)
        prereq[b].add(a)
        if a not in prereq:
            prereq[a] = prereq[a]  # ensure key exists

    done = set()
    available = []
    for s in sorted(steps):
        if not prereq[s]:
            available.append(s)

    order = []
    while available:
        cur = available.pop(0)  # smallest alphabetically
        order.append(cur)
        done.add(cur)

        # update availability for steps that depend on cur
        for nxt in sorted(steps):
            if nxt in done:
                continue
            if cur in prereq[nxt]:
                prereq[nxt].remove(cur)
            if not prereq[nxt] and nxt not in available:
                available.append(nxt)
                available.sort()

    return "".join(order)

if __name__ == "__main__":
    data = sys.stdin.read()
    print(solve(data))

