import sys

def solve(data: str) -> int:
    nums = list(map(int, data.split()))
    idx = 0

    def parse_node():
        nonlocal idx
        child_count = nums[idx]; idx += 1
        meta_count = nums[idx]; idx += 1

        total_meta_sum = 0
        for _ in range(child_count):
            total_meta_sum += parse_node()

        # add this node's metadata
        total_meta_sum += sum(nums[idx:idx + meta_count])
        idx += meta_count
        return total_meta_sum

    return parse_node()

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    print(solve(data))

if __name__ == "__main__":
    main()

import sys

def solve(data: str) -> int:
    lines = [line.strip() for line in data.strip().splitlines() if line.strip()]
    init_line = lines[0]
    initial = init_line.split(":")[1].strip()

    rules = {}
    for line in lines[1:]:
        pat, res = line.split("=>")
        pat = pat.strip()
        res = res.strip()
        rules[pat] = (res == "#")

    # Represent plants as a set of indices with plants.
    plants = set(i for i, ch in enumerate(initial) if ch == "#")

    # We need 20 generations.
    generations = 20

    for _ in range(generations):
        new_plants = set()
        if not plants:
            plants = set()
        # Only pots within 2 of existing plants can change.
        min_i = min(plants) if plants else 0
        max_i = max(plants) if plants else 0

        for i in range(min_i - 2, max_i + 3):
            pattern = "".join(
                "#" if (i + offset) in plants else "."
                for offset in (-2, -1, 0, 1, 2)
            )
            if rules.get(pattern, False):
                new_plants.add(i)
        plants = new_plants

    return sum(plants)

def main():
    data = sys.stdin.read()
    print(solve(data))

if __name__ == "__main__":
    main()

