import sys

def solve(n: int) -> str:
    # Scores are appended to a growing list; we only need to output 10 digits
    scores = [3, 7]
    a, b = 0, 1  # elf positions

    # We need the 10 recipes immediately after index n-1 (i.e., starting at n)
    target_len = n + 10

    while len(scores) < target_len:
        s = scores[a] + scores[b]
        if s >= 10:
            scores.append(1)
            scores.append(s - 10)
        else:
            scores.append(s)

        a = (a + 1 + scores[a]) % len(scores)
        b = (b + 1 + scores[b]) % len(scores)

    return ''.join(map(str, scores[n:n + 10]))

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data)
    print(solve(n))

if __name__ == "__main__":
    main()

import sys
from collections import deque

def solve(inp: str) -> int:
    grid = [list(line.rstrip("\n")) for line in inp.splitlines() if line.strip("\n") != ""]
    h, w = len(grid), len(grid[0])

    units = []  # (type, hp, ap, y, x)
    for y in range(h):
        for x in range(w):
            c = grid[y][x]
            if c in ("E", "G"):
                units.append([c, 200, 3, y, x])
                grid[y][x] = "."

    def reading_key(u):
        return (u[3], u[4])

    def adjacent_positions(y, x):
        return [(y - 1, x), (y, x - 1), (y, x + 1), (y + 1, x)]  # up, left, right, down

    def in_bounds(y, x):
        return 0 <= y < h and 0 <= x < w

    def unit_at(y, x):
        for u in units:
            if u[3] == y and u[4] == x and u[0] in ("E", "G") and u[1] > 0:
                return u
        return None

    def alive_units():
        return [u for u in units if u[1] > 0]

    rounds = 0
    while True:
        # order by reading order at start of each round
        order = sorted(alive_units(), key=reading_key)

        # if no targets at start of round, combat ends immediately (no full round counted)
        elves_alive = any(u[0] == "E" for u in order)
        goblins_alive = any(u[0] == "G" for u in order)
        if not elves_alive or not goblins_alive:
            break

        for u in order:
            if u[1] <= 0:
                continue

            # check if targets remain
            targets = [t for t in alive_units() if t[0] != u[0]]
            if not targets:
                # combat ends during this round; do not count this round as full
                total_hp = sum(x[1] for x in alive_units())
                return rounds * total_hp

            # determine if already in range to attack
            enemy_adj = []
            for ny, nx in adjacent_positions(u[3], u[4]):
                if not in_bounds(ny, nx):
                    continue
                v = unit_at(ny, nx)
                if v is not None and v[0] != u[0] and v[1] > 0:
                    enemy_adj.append(v)

            if not enemy_adj:
                # compute squares in range of any target: open '.' adjacent to targets
                in_range = set()
                for t in targets:
                    ty, tx = t[3], t[4]
                    for ny, nx in adjacent_positions(ty, tx):
                        if not in_bounds(ny, nx):
                            continue
                        if grid[ny][nx] != ".":
                            continue
                        # must not be occupied by another unit
                        if unit_at(ny, nx) is None:
                            in_range.add((ny, nx))

                if not in_range:
                    continue  # cannot reach any in-range square

                # BFS from current position to find nearest reachable in_range squares
                start = (u[3], u[4])
                q = deque([start])
                dist = {start: 0}
                found_dist = None
                reachable_targets = []

                while q:
                    y, x = q.popleft()
                    d = dist[(y, x)]
                    if found_dist is not None and d > found_dist:
                        break
                    if (y, x) in in_range:
                        found_dist = d
                        reachable_targets.append((y, x))
                        continue

                    for ny, nx in adjacent_positions(y, x):
                        if not in_bounds(ny, nx):
                            continue
                        if grid[ny][nx] != ".":
                            continue
                        if unit_at(ny, nx) is not None:
                            continue
                        if (ny, nx) not in dist:
                            dist[(ny, nx)] = d + 1
                            q.append((ny, nx))

                # choose destination square in reading order among nearest
                reachable_targets.sort()
                dest_y, dest_x = reachable_targets[0]

                # choose first step toward destination along shortest path
                # BFS from start but stop when reaching any neighbor that is on a shortest path to dest
                # We'll compute distances from start and from dest (reverse BFS) to ensure shortest path.
                # Since movement is unweighted, we can do:
                # - compute dist_from_start to all
                # - compute dist_to_dest by BFS from dest
                def bfs_from(source):
                    q2 = deque([source])
                    d2 = {source: 0}
                    while q2:
                        cy, cx = q2.popleft()
                        for ny, nx in adjacent_positions(cy, cx):
                            if not in_bounds(ny, nx):
                                continue
                            if grid[ny][nx] != ".":
                                continue
                            if unit_at(ny, nx) is not None and (ny, nx) != (u[3], u[4]):
                                continue
                            if (ny, nx) not in d2:
                                d2[(ny, nx)] = d2[(cy, cx)] + 1
                                q2.append((ny, nx))
                    return d2

                dist_start = bfs_from(start)
                dist_dest = bfs_from((dest_y, dest_x))
                best_step = None
                best_step_dist = None

                for ny, nx in adjacent_positions(u[3], u[4]):
                    if not in_bounds(ny, nx):
                        continue
                    if grid[ny][nx] != ".":
                        continue
                    if unit_at(ny, nx) is not None:
                        continue
                    if (ny, nx) in dist_start and (ny, nx) in dist_dest:
                        # shortest path condition:
                        # dist_start[step] + dist_dest[step] == dist_start[dest]
                        if dist_start[(ny, nx)] + dist_dest[(ny, nx)] == dist_start[(dest_y, dest_x)]:
                            step_d = dist_start[(ny, nx)]
                            if best_step is None or step_d < best_step_dist or (step_d == best_step_dist and (ny, nx) < best_step):
                                best_step = (ny, nx)
                                best_step_dist = step_d

                if best_step is not None:
                    u[3], u[4] = best_step

                # after moving, check adjacent enemies again
                enemy_adj = []
                for ny, nx in adjacent_positions(u[3], u[4]):
                    if not in_bounds(ny, nx):
                        continue
