def parse_input(text: str):
    depth = None
    tx = ty = None
    for line in text.strip().splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith("depth:"):
            depth = int(line.split(":")[1].strip())
        elif line.startswith("target:"):
            coords = line.split(":")[1].strip()
            a, b = coords.split(",")
            tx, ty = int(a), int(b)
    return depth, tx, ty

def solve(depth, tx, ty):
    # Part 1: risk level
    # Need erosion/type for rectangle [0..tx] x [0..ty]
    erosion = [[0] * (ty + 1) for _ in range(tx + 1)]
    risk = 0

    for y in range(ty + 1):
        for x in range(tx + 1):
            if (x == 0 and y == 0) or (x == tx and y == ty):
                gi = 0
            elif y == 0:
                gi = x * 16807
            elif x == 0:
                gi = y * 48271
            else:
                gi = erosion[y][x - 1] * erosion[y - 1][x]
            e = (gi + depth) % MOD
            erosion[y][x] = e
            t = e % 3
            risk += t  # rocky=0, wet=1, narrow=2

    # Part 2: shortest time with tool constraints
    # Tools: 0=climbing gear, 1=torch, 2=neither
    # Region types: 0 rocky, 1 wet, 2 narrow
    # Allowed tools per type:
    # rocky: gear or torch -> {0,1}
    # wet: gear or neither -> {0,2}
    # narrow: torch or neither -> {1,2}
    allowed = {
        0: (0, 1),
        1: (0, 2),
        2: (1, 2),
    }

    # We may need to go beyond target. A safe bound:
    # typical AoC solution uses margin 50 or so; we can compute a tighter one:
    # shortest path won't need to go too far because moving costs and tool switches.
    margin = 50
    max_x = tx + margin
    max_y = ty + margin

    # Precompute erosion for the expanded grid
    erosion2 = [[0] * (max_x + 1) for _ in range(max_y + 1)]
    for y in range(max_y + 1):
        for x in range(max_x + 1):
            if (x == 0 and y == 0) or (x == tx and y == ty):
                gi = 0
            elif y == 0:
                gi = x * 16807
            elif x == 0:
                gi = y * 48271
            else:
                gi = erosion2[y][x - 1] * erosion2[y - 1][x]
            erosion2[y][x] = (gi + depth) % MOD

    def region_type(x, y):
        return erosion2[y][x] % 3

    # Dijkstra over (x,y,tool)
    # Start at (0,0) with torch (tool=1)
    # Goal at (tx,ty) with torch (tool=1)
    INF = 10**18
    dist = [[[INF] * 3 for _ in range(max_x + 1)] for __ in range(max_y + 1)]
    dist[0][0][1] = 0
    pq = [(0, 0, 0, 1)]  # (time, x, y, tool)

    while pq:
        d, x, y, tool = heapq.heappop(pq)
        if d != dist[y][x][tool]:
            continue
        if x == tx and y == ty and tool == 1:
            return risk, d

        # Move to adjacent cells if tool allowed there
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = x + dx, y + dy
            if nx < 0 or ny < 0 or nx > max_x or ny > max_y:
                continue
            if tool in allowed[region_type(nx, ny)]:
                nd = d + 1
                if nd < dist[ny][nx][tool]:
                    dist[ny][nx][tool] = nd
                    heapq.heappush(pq, (nd, nx, ny, tool))

        # Switch tools (7 minutes) if new tool allowed in current region
        cur_type = region_type(x, y)
        for new_tool in allowed[cur_type]:
            if new_tool == tool:
                continue
            nd = d + 7
            if nd < dist[y][x][new_tool]:
                dist[y][x][new_tool] = nd
                heapq.heappush(pq, (nd, x, y, new_tool))

    raise RuntimeError("No path found (increase margin).")

def main():
    text = sys.stdin.read()
    depth, tx, ty = parse_input(text)
    risk, minutes = solve(depth, tx, ty)

    # Problem statement asks for Part Two answer.
    # Output format: single integer (fewest minutes).
    print(minutes)

