import re

def solve(data: str) -> int:
    bots = []
    pat = re.compile(r"pos=<(-?\d+),(-?\d+),(-?\d+)>,\s*r=(\d+)")
    for line in data.strip().splitlines():
        line = line.strip()
        if not line:
            continue
        m = pat.match(line)
        if not m:
            continue
