import sys

def run_intcode(program):
    mem = program[:]  # copy
    ip = 0
    while True:
        op = mem[ip]
        if op == 99:
            break
        a_pos, b_pos, out_pos = mem[ip + 1], mem[ip + 2], mem[ip + 3]
        if op == 1:
            mem[out_pos] = mem[a_pos] + mem[b_pos]
        elif op == 2:
            mem[out_pos] = mem[a_pos] * mem[b_pos]
        else:
            raise ValueError(f"Unknown opcode {op} at position {ip}")
        ip += 4
    return mem[0]

def solve():
    data = sys.stdin.read().strip()
    program = list(map(int, data.split(',')))
    program[1] = 12
    program[2] = 2
    print(run_intcode(program))

if __name__ == "__main__":
    solve()

import sys

def solve(data: str) -> int:
    lines = [line.strip() for line in data.strip().splitlines() if line.strip()]
    if len(lines) < 2:
        return 0

    def trace(path: str):
        x = y = 0
        steps = 0
        visited = {}  # (x,y) -> first steps to reach
        for token in path.split(','):
            d = token[0]
            n = int(token[1:])
            dx, dy = 0, 0
            if d == 'U':
                dy = 1
            elif d == 'D':
                dy = -1
            elif d == 'L':
                dx = -1
            elif d == 'R':
                dx = 1
            else:
                raise ValueError(f"Unknown direction: {d}")

            for _ in range(n):
                x += dx
                y += dy
                steps += 1
                if (x, y) not in visited:
                    visited[(x, y)] = steps
        return visited

    wire1 = trace(lines[0])
    wire2 = trace(lines[1])

    best = None
    for p, s1 in wire1.items():
        if p in wire2:
            total = s1 + wire2[p]
            if best is None or total < best:
                best = total

    return best if best is not None else 0


def main():
    data = sys.stdin.read()
    ans = solve(data)
    print(ans)

if __name__ == "__main__":
    main()

