import sys

def count_valid_passwords(low, high):
    low = int(low)
    high = int(high)

    def is_valid(n):
        s = str(n)
        # six-digit number assumed by range, but keep it safe
        if len(s) != 6:
            return False

        has_double = False
        for i in range(5):
            if s[i] == s[i + 1]:
                has_double = True
            if s[i] > s[i + 1]:  # never decrease
                return False
        return has_double

    cnt = 0
    for x in range(low, high + 1):
        if is_valid(x):
            cnt += 1
    return cnt

