import sys

def count_passwords_part1(lo, hi):
    def ok(n):
        s = str(n)
        # never decrease
        if any(s[i] > s[i+1] for i in range(5)):
            return False
        # at least one adjacent equal
        if not any(s[i] == s[i+1] for i in range(5)):
            return False
        return True

    return sum(1 for n in range(lo, hi + 1) if ok(n))


def count_passwords_part2(lo, hi):
    def ok(n):
        s = str(n)
        # never decrease
        if any(s[i] > s[i+1] for i in range(5)):
            return False

        # find groups of equal digits; need at least one group of exactly length 2
        i = 0
        has_exact_two = False
        while i < 6:
            j = i
            while j < 6 and s[j] == s[i]:
                j += 1
            if j - i == 2:
                has_exact_two = True
            i = j
        return has_exact_two

    return sum(1 for n in range(lo, hi + 1) if ok(n))


def solve():
    data = sys.stdin.read().strip()
    if not data:
        return
    lo_str, hi_str = data.split('-')
    lo, hi = int(lo_str), int(hi_str)

    # Part Two requested
    ans = count_passwords_part2(lo, hi)
    print(ans)

if __name__ == "__main__":
    solve()

